function today(){let html=baseToday();html=html.replace('<div class="compose-footer">','<label class="field">保存后<select id="analysis-intent"><option value="private">只保存，不交给 AI</option><option value="now">保存并分析</option></select></label><div class="compose-footer">');html=html.replace('data-action="save-event"','data-full="save-event"');const start=html.indexOf('<section class="card care-card">'),end=html.indexOf('<section class="card wallet-card">',start);if(start>=0&&end>start)html=html.slice(0,start)+careCard()+html.slice(end);const note=state.noticeData,notice=note.published&&state.dismissedNotice!==note.version?`<div class="banner"><div><strong>${esc(note.title)}</strong><p>${esc(note.body)}</p></div><button class="text-button" data-full="dismiss-announcement">收起</button></div>`:'';const recent=state.records.filter(r=>r.savedDay===state.day&&!r.revoked).slice(0,3);return notice+`<div class="quick-links"><a href="#pending">待处理 ${state.records.filter(r=>r.kind==='event'&&r.aiConsent===true&&!r.settled&&!r.revoked).length} 项</a><a href="#diary">写晚间日记</a><a href="#guide">完整功能目录 →</a></div>`+html+`<section class="card mt"><div class="section-title"><h2>今天已经留下的</h2><a href="#handbook">全部记录 →</a></div>${recent.map(recordRow).join('')||'<p class="empty">今天的事件与日记会出现在这里。</p>'}</section>`}
function legacyCareCard(){return `<section class="card care-card"><div class="section-title"><h3>也记得照顾自己</h3><button class="switch ${state.careVisible?'on':''}" role="switch" aria-checked="${state.careVisible}" aria-label="显示生活清单" data-full="toggle-care"></button></div>${state.careVisible?['睡眠','饮食','活动'].map((n,i)=>`<div class="mini-item"><span class="icon-box">${icon(['moon','coffee','today'][i])}</span><div><strong>${n}</strong><p>${esc(state.care[state.day+'@'+n]||'还没记录，不代表没有做')}</p><div class="row wrap"><button class="text-button" data-action="care" data-id="${n}">${state.care[state.day+'@'+n]?'查看 / 修改':'简单记一下'}</button><button class="text-button" data-action="care-skip" data-id="${n}">今天跳过</button></div></div></div>`).join(''):'<p class="small muted">生活清单已收起，随时可以开启。</p>'}<p class="care-rest">午睡、小憩、远眺等基本休息一直自由。</p></section>`}
function recordRow(r){return `<article class="list-row"><div><div class="row wrap"><span class="tag">${r.kind==='diary'?'日记':'事件'}</span><span class="small muted">${r.contentDay} · 保存 ${r.savedDay}</span>${r.revoked?'<span class="tag orange">已撤销</span>':''}</div><p class="record-excerpt">${esc(r.text.slice(0,120))}${r.text.length>120?'…':''}</p><button class="text-button" data-action="open-record" data-id="${r.id}">查看${r.kind==='diary'?'日记与回顾':'原文与分析'} →</button></div></article>`}
function my(){const entries=[['models','模型与 AI','判定：'+modelCaption()+'；辅助：'+(state.auxModel?modelCaption(state.auxModel):'沿用判定模型')],['security','账号与安全','密码、邮箱、设备会话'],['export','导出与本地保存','Markdown / HTML / JSON / CSV'],['questionnaire','详细问卷与背景','可跳过、可恢复，不覆盖旧评估'],['preferences','显示与扩展设置','属性显示、旧扩展开关说明'],['subdimensions','高分后的细分方向','查看子维度候选及确认'],['profile','娱乐额度与奖励约定','基础时间、阶段与长期奖励偏好'],['comeback','回归时更新近况','从现在继续，不补造过去'],['care-settings','照顾自己设置','自己选择项目，不固定数量'],['anchors','AI 如何判断','查看事实依据，不手动校准加点'],['announcements','站点公告','已发布公告与历史'],['feedback','意见与问题','只有你与授权管理员可见'],['auth','登录与注册体验','无需邀请码，含邮箱恢复'],['guide','完整系统体验目录','查看全部模块，切换管理身份']];return heading('我的','个人设置各有入口，日常记录留在日常。')+`<section class="card mb"><div class="row"><span class="avatar">林</span><div><h2>${esc(state.account.name)}</h2><p class="small muted">${esc(state.account.username)} · Asia/Shanghai</p></div></div><div class="stats">${[[daysMetric('diary').total,'日记天数'],[daysMetric('event').total,'事件记录天数'],[state.coins,'可用金币']].map(([v,n])=>`<div class="stat"><strong>${v}</strong><span>${n}</span></div>`).join('')}</div></section><div class="two-col">${[entries.slice(0,6),entries.slice(6)].map(list=>`<section class="card">${list.map(([r,n,d])=>`<a href="#${r}" class="list-row"><div><h3>${n}</h3><small>${esc(d)}</small></div>${icon('arrow')}</a>`).join('')}</section>`).join('')}</div>`}
function legacyAttributeChanges(r){if(!r.settled||r.revoked||r.reused||r.sameFactAs)return [];const value=r.suggestion?.attribute||r.attribute||'';const found=dimensions.find(d=>value.startsWith(d)),number=value.match(/[+-]\s*(\d+(?:\.\d+)?)/);return found&&number?[{name:found,delta:Number(number[0].replace(/\s/g,''))}]:[]}
function attributeValue(name){return Math.max(0,Math.min(100,Math.round(((state.profile.attributes?.[name]??(state.profile.evaluated&&name==='智力'?54:50))+state.records.flatMap(attributeChanges).filter(a=>a.name===name).reduce((n,a)=>n+a.delta,0))*100)/100))}
function radar(){const visibleDimensions=dimensions.filter(n=>state.dimensionVisibility[n]!=='hidden');const cx=180,cy=175,radius=115,at=(i,r)=>[cx+Math.cos(i*Math.PI*2/Math.max(1,visibleDimensions.length)-Math.PI/2)*r,cy+Math.sin(i*Math.PI*2/Math.max(1,visibleDimensions.length)-Math.PI/2)*r];return `<svg class="radar" viewBox="0 0 360 360" role="img" aria-label="13维属性雷达图">${[.25,.5,.75,1].map(f=>`<polygon points="${visibleDimensions.map((_,i)=>at(i,radius*f).join(',')).join(' ')}" fill="none" stroke="#e2e7f3"/>`).join('')}${visibleDimensions.map((_,i)=>`<line x1="${cx}" y1="${cy}" x2="${at(i,radius)[0]}" y2="${at(i,radius)[1]}" stroke="#e2e7f3"/>`).join('')}<polygon points="${visibleDimensions.map((d,i)=>at(i,radius*attributeValue(d)/100).join(',')).join(' ')}" fill="#4356df28" stroke="#4356df" stroke-width="2"/>${visibleDimensions.map((d,i)=>{const [x,y]=at(i,radius+32);return `<text x="${x}" y="${y}" text-anchor="middle" dominant-baseline="middle">${d} ${attributeValue(d)}</text>`}).join('')}</svg>`}
function growth(){return heading('看见自己的积累','13 维游戏刻度，依据你确认的行动逐项累积。')+subnav()+`<div class="two-col"><section class="card"><h2>能力与生活状态</h2><p class="small muted mt">中性起点 50 是未评估，不直接标为“熟练”。每项可展开查看入账依据。</p>${dimensions.filter(n=>state.dimensionVisibility[n]!=='hidden').map(n=>`<details class="attribute-row"><summary><span>${n}</span><strong>${attributeValue(n)} / 100</strong></summary><div class="progress"><div style="width:${attributeValue(n)}%"></div></div><div class="body">${state.records.filter(r=>attributeChanges(r).some(a=>a.name===n)).map(r=>`<button class="text-button" data-action="open-record" data-id="${r.id}">${esc(r.text.slice(0,32))} · ${esc(r.suggestion?.attribute||r.attribute)}</button>`).join('<br>')||'还没有这项属性的确认入账，从真实行动慢慢累积。'}</div></details>`).join('')}</section><div class="stack"><section class="card"><h2>13 维雷达图</h2>${radar()}<p class="small muted">固定 0～100 轴，用列表核对数值，不只比较面积。</p></section>${metricCards()}<section class="card"><h3>接下来看看</h3><div class="quick-links"><a href="#achievements">成就与里程碑 →</a><a href="#history">属性历史 →</a><a href="#subdimensions">高分后的细分方向 →</a><a href="#challenges">我的挑战 →</a></div></section></div></div><section class="card mt"><h2>最近的记录</h2><div class="heatmap">${Array.from({length:56},(_,i)=>{const day=shift(state.day,i-55),count=state.records.filter(r=>r.savedDay===day&&!r.revoked).length;return `<button data-full="filter-day" data-id="${day}" class="heat-cell level-${Math.min(3,count)}" title="${day} · ${count} 条" aria-label="${day} ${count} 条记录"></button>`}).join('')}</div><p class="small muted">最近 8 周，点击日期回看记录。</p></section>`}
function metricCards(){return [['event','事件记录'],['diary','日记']].map(([k,n])=>{const m=daysMetric(k);return `<section class="card"><h3>${n}</h3><div class="stats">${[[m.total,'累计记录日'],[m.current,'当前连续'],[m.longest,'最长连续']].map(([v,t])=>`<div class="stat"><strong>${v}</strong><span>${t}</span></div>`).join('')}</div><p class="daily-note">内容覆盖 ${m.coverage} 天；按实际保存日计坚持。</p></section>`}).join('')}
function historyPage(){const rows=state.records.filter(r=>attributeChanges(r).length);return back('growth')+heading('属性历史','每一个变化，都能回到对应事实。')+subnav()+`<section class="card">${rows.map(r=>`<div class="list-row"><div><h3>${esc(r.suggestion?.attribute||r.attribute)}</h3><small>${r.settledDay||r.savedDay} · ${esc(r.text.slice(0,80))}</small></div><button class="text-button" data-action="open-record" data-id="${r.id}">查看依据</button></div>`).join('')||'<p class="empty">确认一条事件的建议后，属性变化会出现在这里。</p>'}</section><section class="card mt"><h2>金币流水</h2>${state.ledger.map(x=>`<div class="list-row"><div>${esc(x.title)}<small>${x.day} · ${x.source}</small></div><strong>${x.amount>0?'+':''}${x.amount}</strong></div>`).join('')}</section>`}
function achievementsPage(){return heading('值得记住的里程碑','核实记录，再领取；同一个里程碑不重复发奖。')+subnav()+`<div class="badge-grid">${['event','diary'].flatMap(kind=>[3,7,30].map(target=>{const m=daysMetric(kind),key='streak:'+kind+':'+target;return `<section class="card"><span class="medal">✧</span><h3>连续${kind==='diary'?'写日记':'记录事件'} ${target} 天</h3><p class="subtitle">已核实 ${Math.min(m.longest,target)} / ${target} 天 · ${target===3?10:target===7?30:100} 币</p><button class="btn mt" data-action="claim-achievement" data-kind="${kind}" data-target="${target}" ${m.longest<target||state.claims.includes(key)?'disabled':''}>${state.claims.includes(key)?'已领取':'核实并领取'}</button></section>`})).join('')}</div><section class="card mt"><h2>发现的成就候选</h2>${state.records.find(r=>r.settled&&!r.revoked&&/部署/.test(r.text))?`<p class="quote">首次记录项目部署：已找到一条确认过的事实，可作为发现型里程碑示例。</p><button class="btn soft" data-full="claim-discovery" ${state.claims.includes('discovery-deploy')?'disabled':''}>${state.claims.includes('discovery-deploy')?'已领取':'核实并领取 · 10 币'}</button>`:'<p class="empty">有新的可核实里程碑时会出现在这里。当前没有匹配的发现型示例。</p>'}<details><summary>试试连续 30 天的候选发现</summary><p class="small muted">仅载入虚构历史供体验，不导入真实数据。</p><button class="btn compact mt" data-action="seed-streak">载入 29 天日记样例</button></details></section>`}
function challengeProgress(c){return state.records.filter(r=>r.settled&&!r.revoked&&!r.reused&&!r.sameFactAs&&r.suggestion?.main&&r.savedDay>=(c.acceptedDay||state.day)).length}
function challengesPage(){return heading('给自己一个小挑战','接受时看清约定，完成后依据实际记录结算。')+subnav()+`<section class="card">${state.challenges.map(c=>`<div class="mb"><div class="row between"><h2>${esc(c.title)}</h2><span class="tag">${({candidate:'待接受',accepted:'进行中',settled:'已结算',abandoned:'已放弃'})[c.status]}</span></div><p class="subtitle">${c.period==='weekly'?'每周':'每日'}挑战示例 · 目标 ${c.target} 次 · 押金 ${c.deposit} 币 · 达成奖励 ${c.reward} 币</p><p class="small muted mt">不同事实计数：${Math.min(challengeProgress(c),c.target)} / ${c.target}。同一事实从计划或计时进入不再算一次。</p><div class="row wrap mt">${c.status==='candidate'?`<button class="btn primary" data-full="accept-challenge" data-id="${c.id}">查看并接受</button>`:c.status==='accepted'?`<button class="btn primary" data-full="settle-challenge" data-id="${c.id}">核对与结算</button><button class="btn" data-full="abandon-challenge" data-id="${c.id}">未完成 / 意外说明</button>`:'<p class="note">'+esc(c.result||'当次结果已保存')+'</p>'}<a href="#plans" class="text-button">安排具体行动 →</a></div></div>`).join('')}</section>`}
function reportsPage(){return heading('周期回顾','把记录整理成回顾，不再记成新的事件或日记。')+subnav()+`<section class="card"><label class="field">回顾范围<select id="report-period"><option value="7">最近 7 天</option><option value="30">最近 30 天</option></select></label><button class="btn primary" data-full="generate-report">生成回顾示例</button></section><section class="card mt"><h2>已经保存的回顾</h2>${state.reports.slice().reverse().map(r=>`<details><summary>${r.start}～${r.end} · ${r.title}</summary><p class="quote">${esc(r.text)}</p><p class="small muted">依据当时 ${r.sources.length} 条原文快照；原文后续变化不覆盖这份回顾。</p></details>`).join('')||'<p class="empty">生成后先看预览，确认保存到这里。</p>'}</section>`}
function guide(){return heading('完整系统体验目录','日常、成长、个人设置与管理，全部在这一份 Demo 中体验。')+`<section class="card"><div class="section-title"><h2>统一体验入口</h2><button class="btn soft" data-full="${state.role==='admin'?'leave-admin':'enter-admin'}">${state.role==='admin'?'返回普通体验':'进入管理体验'}</button></div><p class="note">账号、模型调用、邮件和金额均为本机模拟。基础娱乐独立免费时长仍是待你确认的方案；通用 AI 聊天、复杂预约分期和 App / 小程序按之前决定暂缓。</p><div class="guide-links">${routeCatalog.filter(r=>state.role==='admin'?r[3]==='管理':r[3]!=='管理').map(([r,n,d])=>`<a href="#${r==='record'&&!state.activeRecord?'handbook':r}"><div><strong>${n}</strong><small>${d}</small></div>${icon('arrow')}</a>`).join('')}</div></section><section class="card mt"><h2>记录体验意见</h2><label class="field">想调整的地方<textarea id="review-note">${esc(state.review.note||'')}</textarea></label><div class="row wrap"><button class="btn primary" data-action="save-opinion">保存本机意见</button><button class="btn" data-action="download-opinion">下载意见</button></div></section>`}
const anchorExamples=[['study','独立练习与整理','智力','按真实投入、掌握情况与成果判断，不因久坐自动加分。',.4],['movement','身体活动','体能','结合实际强度和恢复情况，不把单次表现等同永久能力。',.4],['rest','恢复与照顾自己','健康','基本休息无需兑换，也不要求为了奖励而记录。',.2]];
function legacyAnchorsPage(){return back('my')+heading('量化参考与个人校准','理解游戏刻度的依据，也可以记录更适合自己的参考。')+`<section class="card">${anchorExamples.map(([id,n,dim,note,value])=>`<div class="list-row"><div><h3>${n} · ${dim}</h3><small>${note}</small><p class="small muted">参考 ${value}，个人校准 ${state.anchorValues[id]??'未设置'}</p></div><button class="btn compact" data-full="calibrate-anchor" data-id="${id}">校准</button></div>`).join('')}<p class="note mt">校准保留为个人参考，不修改已确认的历史。这里只演示已有量化参考入口，不声称这些数值是精确能力测量。</p></section>`}
function preferencesPage(){return back('my')+heading('显示与扩展设置','隐藏显示不会删除历史或停止累计。')+`<section class="card"><h2>属性维度显示</h2>${dimensions.map(n=>`<label class="field">${n}<select data-dimension="${n}"><option value="show" ${state.dimensionVisibility[n]!=='hidden'?'selected':''}>显示</option><option value="hidden" ${state.dimensionVisibility[n]==='hidden'?'selected':''}>隐藏显示，继续累计</option></select></label>`).join('')}</section><details class="card mt"><summary>旧扩展开关 · 暂不可操作</summary><p class="small muted mt">沿用项目当前状态：这组旧开关尚未接入已交付模块，不在 Demo 中把它们擅自变成可操作开关。成就、计划、记录天数和奖励商店各有完整入口。</p></details>`}
function subdimensionsPage(){const candidates=dimensions.filter(n=>attributeValue(n)>=95||(state.subdimensionSample&&n==='智力'));return back('growth')+heading('高分后的细分方向','主维度保留，AI 提议细分名称，由你勾选后确认。')+`<section class="card"><p class="note">沿用现有入口的 95 分候选阈值。当前候选不代表重新测量能力，也不会自动改写已入账分数。</p>${candidates.map(n=>`<div class="list-row"><div><h3>${n}${state.subdimensionSample&&attributeValue(n)<95?' · 高分样例':''}</h3><small>${state.subdimensions[n]?.length?'已确认：'+esc(state.subdimensions[n].join('、')):'可以生成细分名称建议'}</small></div><button class="btn compact" data-full="propose-subdimensions" data-id="${n}">提议 / 查看</button></div>`).join('')||'<p class="empty">当前没有达到阈值的属性。可以载入单独的高分流程样例。</p>'}<details><summary>预览高分流程</summary><button class="btn compact mt" data-full="sample-subdimensions">载入高分候选样例</button><p class="small muted">只让此页显示候选，不修改你的基线、属性或金币。</p></details></section>`}
